"""Readable YAML for the primitive Compose documents generated by the panel."""
import json
import math
import re


def scalar(value):
    if value is None:return 'null'
    if isinstance(value,bool):return 'true' if value else 'false'
    if isinstance(value,str):return json.dumps(value,ensure_ascii=False)
    if isinstance(value,(int,float)) and (not isinstance(value,float) or math.isfinite(value)):return str(value)
    raise TypeError('Unsupported Compose value: '+type(value).__name__)


def compose_yaml(document):
    def key(value):
        if not isinstance(value,str):raise TypeError('Compose keys must be strings')
        if re.fullmatch(r'[A-Za-z_][A-Za-z0-9_.-]*',value) and value.lower() not in ('yes','no','on','off','true','false','null','~'):
            return value
        return scalar(value)
    def lines(value,level=0):
        pad=' '*level
        if isinstance(value,dict):
            for name,item in value.items():
                prefix=pad+key(name)+':'
                if isinstance(item,(dict,list)) and item:
                    yield prefix;yield from lines(item,level+2)
                else:yield prefix+' '+('{}' if item=={} else '[]' if isinstance(item,list) and not item else scalar(item))
        elif isinstance(value,list):
            for item in value:
                if isinstance(item,(dict,list)) and item:
                    yield pad+'-';yield from lines(item,level+2)
                else:yield pad+'- '+('{}' if item=={} else '[]' if isinstance(item,list) and not item else scalar(item))
        else:yield pad+scalar(value)
    return '\n'.join(lines(document))+'\n'
